config.script:
itemId = self.view.custom.itemTable.selection.data[0].itemId
itemClassId = None
if self.view.custom.userAction.canUpdate: self.view.getChild("root").openEditor(itemId, itemClassId)
else: system.perspective.sendMessage('showFailerToast', 'No permissions to update configure this item.')

return

messageHandlers.script:
system.perspective.print("userResponseDelete() msg rcvd with %s"%payload)
if payload.has_key('userInput') and payload['userInput'] == 'OK':	self.deleteItemUnits()

return

customMethods.script:

for row in self.view.custom.itemUnits.selection.data:
	retVal, msg = system.kanoa.item.deleteItemUnit(row['itemUnitId'], self.view.custom.security.userId)
	if msg: system.perspective.sendMessage('showWarningToast', {'message': 'This item unit cannot be deleted. %s'%msg})
	else: system.perspective.sendMessage('showSuccessfulToast', {'message': 'This item unit has been deleted.'})

self.view.refreshBinding("custom.itemUnits.data")

return

transforms.code:

itemUnitId = value['data'][0]['itemUnitId'] if len(value['data']) > 0 else None
security = value['security']
canCreate = False
canEdit = False
if security['userCRUD'] is not None and security['userId'] is not None:
	if security['userCRUD']['isGatewayAdmin'] or security['userCRUD']['configureItems']['enabled']: 
		canCreate = True
		canEdit = True if itemUnitId else False

return {"canCreate": canCreate, "canDelete": canEdit, "canRead": True, "canUpdate": canEdit}
